import jep.Jep;
import jep.JepException;

public class TestDictWithNone {
    public static void main(final String[] args) {
        try {
            final Jep jep = new Jep(false);
            jep.eval("x = {'abc': 111, 'bcd': '222', 'cde': None}");
            jep.eval("def gx():\n\treturn x");
            final Object x = jep.getValue("x");
            final Object xs = jep.invoke("gx");
            System.out.println("x = " + x);  // should print a HashMap, not null
            System.out.println("xs = " + xs);  // should print a HashMap, not null
            System.out.println("x type = " + (x == null ? "null" : x.getClass().getName()));
            System.out.println("xs type = " + (xs == null ? "null" : xs.getClass().getName()));
            jep.close();
        } catch (final JepException e) {
            e.printStackTrace();
        }
    }
}
