import jep.Jep;
import jep.JepException;
import java.util.Map;

public class TestDictWithNoneEdgeCases {
    public static void main(final String[] args) {
        try {
            final Jep jep = new Jep(false);

            // Test 1: Dictionary with None value (original issue)
            jep.eval("test1 = {'abc': 111, 'bcd': '222', 'cde': None}");
            final Object test1 = jep.getValue("test1");
            System.out.println("Test 1 (dict with None value): " + test1);
            System.out.println("  Type: " + (test1 == null ? "null" : test1.getClass().getName()));

            // Test 2: Dictionary with None as key (Python doesn't allow this, but let's be safe)
            // Actually Python does allow None as key
            jep.eval("test2 = {None: 'value'}");
            final Object test2 = jep.getValue("test2");
            System.out.println("Test 2 (dict with None key): " + test2);
            System.out.println("  Type: " + (test2 == null ? "null" : test2.getClass().getName()));

            // Test 3: Dictionary with multiple None values
            jep.eval("test3 = {'a': None, 'b': None, 'c': None}");
            final Object test3 = jep.getValue("test3");
            System.out.println("Test 3 (dict with all None values): " + test3);
            System.out.println("  Type: " + (test3 == null ? "null" : test3.getClass().getName()));

            // Test 4: Empty dictionary
            jep.eval("test4 = {}");
            final Object test4 = jep.getValue("test4");
            System.out.println("Test 4 (empty dict): " + test4);
            System.out.println("  Type: " + (test4 == null ? "null" : test4.getClass().getName()));

            // Test 5: Dictionary with None key and None value
            jep.eval("test5 = {None: None}");
            final Object test5 = jep.getValue("test5");
            System.out.println("Test 5 (dict with None key and value): " + test5);
            System.out.println("  Type: " + (test5 == null ? "null" : test5.getClass().getName()));

            // Test 6: Nested dictionary with None values
            jep.eval("test6 = {'outer': {'inner': None}}");
            final Object test6 = jep.getValue("test6");
            System.out.println("Test 6 (nested dict with None): " + test6);
            System.out.println("  Type: " + (test6 == null ? "null" : test6.getClass().getName()));

            jep.close();
            System.out.println("\nAll tests passed!");
        } catch (final JepException e) {
            e.printStackTrace();
        }
    }
}
