import jep.Jep;
import jep.JepException;
import java.util.Map;
import java.util.List;

public class TestDictWithNoneFinal {
    public static void main(final String[] args) {
        try {
            final Jep jep = new Jep(false);

            // Test from the bug report
            jep.eval("x = {'abc': 111, 'bcd': '222', 'cde': None}");
            jep.eval("def gx():\n\treturn x");
            final Object x = jep.getValue("x");
            final Object xs = jep.invoke("gx");

            System.out.println("=== Bug Report Test ===");
            System.out.println("x = " + x);
            System.out.println("xs = " + xs);
            System.out.println("x type = " + (x == null ? "null" : x.getClass().getName()));
            System.out.println("xs type = " + (xs == null ? "null" : xs.getClass().getName()));

            // Verify values
            Map<?, ?> xMap = (Map<?, ?>) x;
            if (!xMap.get("abc").equals(111)) {
                throw new AssertionError("Expected abc=111, got " + xMap.get("abc"));
            }
            if (!xMap.get("bcd").equals("222")) {
                throw new AssertionError("Expected bcd='222', got " + xMap.get("bcd"));
            }
            if (xMap.get("cde") != null) {
                throw new AssertionError("Expected cde=null, got " + xMap.get("cde"));
            }
            System.out.println("All assertions passed!");

            // Test with None in list inside dict
            jep.eval("y = {'list_with_none': [1, None, 3]}");
            Map<?, ?> yMap = (Map<?, ?>) jep.getValue("y");
            List<?> yList = (List<?>) yMap.get("list_with_none");
            System.out.println("\n=== List with None inside dict ===");
            System.out.println("y = " + yMap);
            System.out.println("list = " + yList);
            if (yList.get(0) != 1) throw new AssertionError("Expected 1");
            if (yList.get(1) != null) throw new AssertionError("Expected null, got " + yList.get(1));
            if (yList.get(2) != 3) throw new AssertionError("Expected 3");
            System.out.println("All assertions passed!");

            jep.close();
            System.out.println("\nAll tests passed successfully!");
        } catch (final JepException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }
}
